// Recovers stale deep links whose #fragment was generated by a previous
// heading-ID scheme. The redirect map is only fetched when the current URL
// hash fails to resolve, so regular visits cost nothing.
export function initAnchorRedirect() {
  window.addEventListener('hashchange', applyRedirect);

  if (window.location.hash) {
    applyRedirect();
  }
}

function applyRedirect() {
  const rawHash = window.location.hash.slice(1);
  if (!rawHash) {
    return;
  }

  const decodedHash = decodeHash(rawHash);
  if (document.getElementById(decodedHash)) {
    scrollIntoViewIfHidden(decodedHash);
    return;
  }

  fetchAnchorMap()
    .then(map => {
      const pageMap = map && map[window.location.pathname];
      const target = pageMap && pageMap[decodedHash];
      if (target && target !== decodedHash) {
        window.history.replaceState(null, '', '#' + target);
        scrollIntoViewIfHidden(target);
      }
    })
    .catch(() => {});
}

function scrollIntoViewIfHidden(id) {
  const element = document.getElementById(id);
  if (element) {
    element.scrollIntoView();
  }
}

let anchorMapPromise;

function fetchAnchorMap() {
  if (!anchorMapPromise) {
    anchorMapPromise = fetch('/anchorRedirects.json').then(response =>
      response.ok ? response.json() : {}
    );
  }
  return anchorMapPromise;
}

function decodeHash(rawHash) {
  try {
    return decodeURIComponent(rawHash);
  } catch {
    return rawHash;
  }
}
